PRODUCTION_SOURCE = '"""\nOLA-048\nOracle Live Shadow Lineage Graph Binding Contract\n\nFinal canonical graph-binding boundary before OLA-030 production integration.\n\nPurpose:\n- accept the existing production persistence router\n- accept the existing OLA-030 production scheduler cycle callable\n- create one OLA-047 shared production composition\n- expose the OLA-042 staged persistence router as the exact router that must be\n  injected into both OracleLiveReadOnlyAcquisitionRuntime and OLA-017\n- expose the OLA-046 scheduler adapter as the exact callable that must be\n  injected into ShadowCycleRunnerBinding\n- prove both exposed bindings share one OLA-044 lineage production state\n- preserve the original production persistence router and scheduler callable\n  by exact object identity\n\nThis contract performs graph binding only.\nIt does not acquire data, persist observations, advance a scheduler tick,\ninterpret intelligence, score signals, alert, hand off to Q Series,\nauthorize trading, place orders, move funds, or mutate portfolios.\n\nOracle remains permanently read-only.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Any, Callable\n\nfrom .oracle_persisted_cohort_staging_router import (\n    OraclePersistedCohortStagingRouter,\n)\nfrom .oracle_scheduler_lineage_production_adapter import (\n    OracleSchedulerLineageProductionAdapter,\n)\nfrom .oracle_scheduler_lineage_production_composition import (\n    OracleSchedulerLineageProductionComposition,\n)\n\n\nSCHEMA_VERSION = "OLA-048"\nENGINE_ID = "OLA-048"\n\nREAD_ONLY = True\nEXECUTION_ALLOWED = False\nEXECUTION_ADAPTER_RESOLVED = False\nEXECUTION_ADAPTER_INVOKED = False\nTRADE_AUTHORIZATION_ALLOWED = False\nORDER_PLACEMENT_ALLOWED = False\nFUNDS_MOVED = False\nPORTFOLIO_MUTATED = False\n\n\nclass LiveShadowLineageGraphBindingContractError(ValueError):\n    """Raised when OLA-048 graph binding input is malformed."""\n\n\nclass LiveShadowLineageGraphBindingInvariantError(RuntimeError):\n    """Raised when permanent OLA-048 invariants are violated."""\n\n\n@dataclass(frozen=True, slots=True)\nclass LiveShadowLineageGraphBindingRecord:\n    schema_version: str\n    engine_id: str\n    persistence_router_binding_role: str\n    scheduler_cycle_binding_role: str\n    production_persistence_router_preserved: bool\n    production_scheduler_callable_preserved: bool\n    staged_persistence_router_shared: bool\n    scheduler_adapter_shared: bool\n    shared_production_wiring_identity: bool\n    shared_lineage_state_identity: bool\n    runtime_and_ola017_same_router_required: bool\n    shadow_cycle_runner_uses_scheduler_adapter_required: bool\n    scheduler_kwargs_unchanged: bool\n    scheduler_results_unchanged: bool\n    read_only: bool\n    execution_allowed: bool\n    execution_adapter_resolved: bool\n    execution_adapter_invoked: bool\n    trade_authorization_allowed: bool\n    order_placement_allowed: bool\n    funds_moved: bool\n    portfolio_mutated: bool\n\n    def assert_invariants(self) -> None:\n        if self.schema_version != SCHEMA_VERSION:\n            raise LiveShadowLineageGraphBindingInvariantError(\n                "schema version invariant violated"\n            )\n\n        if self.engine_id != ENGINE_ID:\n            raise LiveShadowLineageGraphBindingInvariantError(\n                "engine identity invariant violated"\n            )\n\n        if self.persistence_router_binding_role != (\n            "runtime_and_ola017_shared_router"\n        ):\n            raise LiveShadowLineageGraphBindingInvariantError(\n                "persistence router binding role invariant violated"\n            )\n\n        if self.scheduler_cycle_binding_role != (\n            "shadow_cycle_runner_cycle_callable"\n        ):\n            raise LiveShadowLineageGraphBindingInvariantError(\n                "scheduler cycle binding role invariant violated"\n            )\n\n        required = (\n            self.production_persistence_router_preserved,\n            self.production_scheduler_callable_preserved,\n            self.staged_persistence_router_shared,\n            self.scheduler_adapter_shared,\n            self.shared_production_wiring_identity,\n            self.shared_lineage_state_identity,\n            self.runtime_and_ola017_same_router_required,\n            self.shadow_cycle_runner_uses_scheduler_adapter_required,\n            self.scheduler_kwargs_unchanged,\n            self.scheduler_results_unchanged,\n        )\n\n        if required != (\n            True,\n            True,\n            True,\n            True,\n            True,\n            True,\n            True,\n            True,\n            True,\n            True,\n        ):\n            raise LiveShadowLineageGraphBindingInvariantError(\n                "OLA-048 graph binding invariant violated"\n            )\n\n        authority = (\n            self.read_only,\n            self.execution_allowed,\n            self.execution_adapter_resolved,\n            self.execution_adapter_invoked,\n            self.trade_authorization_allowed,\n            self.order_placement_allowed,\n            self.funds_moved,\n            self.portfolio_mutated,\n        )\n\n        if authority != (\n            True,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n        ):\n            raise LiveShadowLineageGraphBindingInvariantError(\n                "OLA-048 read-only authority invariants violated"\n            )\n\n\nclass OracleLiveShadowLineageGraphBindingContract:\n    read_only = True\n    execution_allowed = False\n\n    def __init__(\n        self,\n        *,\n        production_persistence_router: Any,\n        production_scheduler_cycle_callable: Callable[..., Any],\n    ) -> None:\n        route_batch = getattr(\n            production_persistence_router,\n            "route_batch",\n            None,\n        )\n\n        if not callable(route_batch):\n            raise LiveShadowLineageGraphBindingContractError(\n                "production_persistence_router must expose callable route_batch"\n            )\n\n        if not callable(\n            production_scheduler_cycle_callable\n        ):\n            raise LiveShadowLineageGraphBindingContractError(\n                "production_scheduler_cycle_callable must be callable"\n            )\n\n        self._production_persistence_router = (\n            production_persistence_router\n        )\n        self._production_scheduler_cycle_callable = (\n            production_scheduler_cycle_callable\n        )\n\n        self._composition = (\n            OracleSchedulerLineageProductionComposition(\n                production_persistence_router=(\n                    production_persistence_router\n                ),\n                scheduler_cycle_callable=(\n                    production_scheduler_cycle_callable\n                ),\n            )\n        )\n\n        self._record = LiveShadowLineageGraphBindingRecord(\n            schema_version=SCHEMA_VERSION,\n            engine_id=ENGINE_ID,\n            persistence_router_binding_role=(\n                "runtime_and_ola017_shared_router"\n            ),\n            scheduler_cycle_binding_role=(\n                "shadow_cycle_runner_cycle_callable"\n            ),\n            production_persistence_router_preserved=(\n                self._composition\n                .production_persistence_router\n                is production_persistence_router\n            ),\n            production_scheduler_callable_preserved=(\n                self._composition\n                .scheduler_cycle_callable\n                is production_scheduler_cycle_callable\n            ),\n            staged_persistence_router_shared=(\n                self.runtime_persistence_router\n                is self.ola017_persistence_router\n                is self._composition\n                .staged_persistence_router\n            ),\n            scheduler_adapter_shared=(\n                self.shadow_cycle_runner_callable\n                is self._composition.scheduler_adapter\n            ),\n            shared_production_wiring_identity=(\n                self._composition\n                .completion_bridge\n                .production_wiring\n                is self._composition.production_wiring\n            ),\n            shared_lineage_state_identity=(\n                self._composition\n                .scheduler_adapter\n                .lineage_completion_bridge\n                .production_wiring\n                is self._composition.production_wiring\n            ),\n            runtime_and_ola017_same_router_required=True,\n            shadow_cycle_runner_uses_scheduler_adapter_required=True,\n            scheduler_kwargs_unchanged=True,\n            scheduler_results_unchanged=True,\n            read_only=READ_ONLY,\n            execution_allowed=EXECUTION_ALLOWED,\n            execution_adapter_resolved=(\n                EXECUTION_ADAPTER_RESOLVED\n            ),\n            execution_adapter_invoked=(\n                EXECUTION_ADAPTER_INVOKED\n            ),\n            trade_authorization_allowed=(\n                TRADE_AUTHORIZATION_ALLOWED\n            ),\n            order_placement_allowed=(\n                ORDER_PLACEMENT_ALLOWED\n            ),\n            funds_moved=FUNDS_MOVED,\n            portfolio_mutated=PORTFOLIO_MUTATED,\n        )\n\n        self._record.assert_invariants()\n\n    @property\n    def production_persistence_router(self) -> Any:\n        return self._production_persistence_router\n\n    @property\n    def production_scheduler_cycle_callable(\n        self,\n    ) -> Callable[..., Any]:\n        return self._production_scheduler_cycle_callable\n\n    @property\n    def composition(\n        self,\n    ) -> OracleSchedulerLineageProductionComposition:\n        return self._composition\n\n    @property\n    def runtime_persistence_router(\n        self,\n    ) -> OraclePersistedCohortStagingRouter:\n        return self._composition.staged_persistence_router\n\n    @property\n    def ola017_persistence_router(\n        self,\n    ) -> OraclePersistedCohortStagingRouter:\n        return self._composition.staged_persistence_router\n\n    @property\n    def shadow_cycle_runner_callable(\n        self,\n    ) -> OracleSchedulerLineageProductionAdapter:\n        return self._composition.scheduler_adapter\n\n    @property\n    def record(\n        self,\n    ) -> LiveShadowLineageGraphBindingRecord:\n        return self._record\n'

TEST_SOURCE = 'from datetime import datetime, timezone\n\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_live_shadow_lineage_graph_binding_contract import (\n    OracleLiveShadowLineageGraphBindingContract,\n)\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n    ObservationRoutingEvidence,\n    RawSourceObservation,\n)\n\n\nT1 = datetime(\n    2026,\n    7,\n    14,\n    23,\n    0,\n    0,\n    tzinfo=timezone.utc,\n)\nT2 = datetime(\n    2026,\n    7,\n    14,\n    23,\n    0,\n    15,\n    tzinfo=timezone.utc,\n)\nT3 = datetime(\n    2026,\n    7,\n    14,\n    23,\n    0,\n    30,\n    tzinfo=timezone.utc,\n)\n\n\ndef build_observation(\n    *,\n    market_id,\n    frame_id,\n    batch_id,\n    yes_ask="0.6140",\n):\n    payload = {\n        "source_market_id": market_id,\n        "yes_bid_dollars": "0.0000",\n        "yes_bid_size_fp": "0.00",\n        "yes_ask_dollars": yes_ask,\n        "yes_ask_size_fp": "40.00",\n        "no_bid_dollars": "0.3860",\n        "no_ask_dollars": "0.0000",\n        "last_price_dollars": "0.0000",\n        "previous_yes_bid_dollars": "0.0000",\n        "previous_yes_ask_dollars": "0.6000",\n        "previous_price_dollars": "0.0000",\n        "volume_fp": "0.00",\n        "volume_24h_fp": "0.00",\n        "open_interest_fp": "0.00",\n        "liquidity_dollars": "0.0000",\n    }\n\n    raw = RawSourceObservation.create(\n        source_observation_id=(\n            "kalshi."\n            + market_id\n            + "."\n            + frame_id\n        ),\n        observed_at=T1,\n        observation_type="market_snapshot",\n        payload=payload,\n        provenance={\n            "source_id": "source.kalshi.market_data",\n            "frame_id": frame_id,\n        },\n    )\n\n    return CanonicalObservation.create(\n        source_id="source.kalshi.market_data",\n        raw_observation=raw,\n        acquired_at=T1,\n        acquisition_batch_id=batch_id,\n    )\n\n\ndef build_cohort(\n    *,\n    cycle_number,\n    changed_market=None,\n):\n    batch_id = f"batch.ola.048.{cycle_number}"\n\n    return tuple(\n        build_observation(\n            market_id=f"KXTEST-GRAPH-{index}",\n            frame_id=f"{cycle_number}-{index}",\n            batch_id=batch_id,\n            yes_ask=(\n                "0.9400"\n                if changed_market\n                == f"KXTEST-GRAPH-{index}"\n                else "0.6140"\n            ),\n        )\n        for index in range(1, 6)\n    )\n\n\nclass FakeProductionPersistenceRouter:\n    def __init__(self):\n        self.batch_call_count = 0\n\n    def route_batch(\n        self,\n        observations,\n        routed_at,\n    ):\n        self.batch_call_count += 1\n\n        return tuple(\n            ObservationRoutingEvidence.create(\n                observation_id=observation.observation_id,\n                routed_at=routed_at,\n                accepted=True,\n                route_id="fake.ola.048.persistence",\n                metadata={\n                    "test": "OLA-048",\n                },\n            )\n            for observation in observations\n        )\n\n    def __call__(\n        self,\n        observation,\n        routed_at,\n    ):\n        return ObservationRoutingEvidence.create(\n            observation_id=observation.observation_id,\n            routed_at=routed_at,\n            accepted=True,\n            route_id="fake.ola.048.persistence.single",\n            metadata={\n                "test": "OLA-048",\n            },\n        )\n\n\nclass FakeProductionSchedulerCycleCallable:\n    def __init__(self):\n        self.call_count = 0\n        self.last_kwargs = None\n\n    def __call__(\n        self,\n        **kwargs,\n    ):\n        self.call_count += 1\n        self.last_kwargs = dict(kwargs)\n\n        return {\n            "schema_version": "OLA-017",\n            "engine_id": "OLA-017",\n            "cycle_status": "completed",\n            "canonical_count": 5,\n            "postgresql_routing_record_delta": 5,\n            "read_only": True,\n            "execution_allowed": False,\n            "projected_by": "existing-ola-030",\n            "kwargs_echo": dict(kwargs),\n        }\n\n\ndef build_binding():\n    persistence_router = (\n        FakeProductionPersistenceRouter()\n    )\n    scheduler_callable = (\n        FakeProductionSchedulerCycleCallable()\n    )\n\n    binding = (\n        OracleLiveShadowLineageGraphBindingContract(\n            production_persistence_router=(\n                persistence_router\n            ),\n            production_scheduler_cycle_callable=(\n                scheduler_callable\n            ),\n        )\n    )\n\n    return (\n        binding,\n        persistence_router,\n        scheduler_callable,\n    )\n\n\ndef run_identity_binding_test():\n    (\n        binding,\n        persistence_router,\n        scheduler_callable,\n    ) = build_binding()\n\n    record = binding.record\n\n    assert record.schema_version == "OLA-048"\n    assert record.engine_id == "OLA-048"\n    assert (\n        binding.production_persistence_router\n        is persistence_router\n    )\n    assert (\n        binding.production_scheduler_cycle_callable\n        is scheduler_callable\n    )\n    assert (\n        binding.runtime_persistence_router\n        is binding.ola017_persistence_router\n    )\n    assert (\n        binding.runtime_persistence_router\n        is binding\n        .composition\n        .staged_persistence_router\n    )\n    assert (\n        binding.shadow_cycle_runner_callable\n        is binding\n        .composition\n        .scheduler_adapter\n    )\n    assert (\n        binding\n        .composition\n        .completion_bridge\n        .production_wiring\n        is binding\n        .composition\n        .production_wiring\n    )\n\n    return binding\n\n\ndef run_three_cycle_binding_test():\n    binding = run_identity_binding_test()\n\n    receipts = []\n\n    for cycle_number, observed_at, changed_market in (\n        (1, T1, None),\n        (2, T2, None),\n        (\n            3,\n            T3,\n            "KXTEST-GRAPH-2",\n        ),\n    ):\n        binding.runtime_persistence_router.route_batch(\n            build_cohort(\n                cycle_number=cycle_number,\n                changed_market=changed_market,\n            ),\n            observed_at,\n        )\n\n        result = binding.shadow_cycle_runner_callable(\n            cycle_completed_at=observed_at,\n            cycle_kwargs={\n                "cycle": cycle_number,\n                "source": "OLA-030",\n            },\n        )\n\n        assert result["projected_by"] == "existing-ola-030"\n        assert result["kwargs_echo"] == {\n            "cycle": cycle_number,\n            "source": "OLA-030",\n        }\n\n        receipts.append(\n            binding\n            .shadow_cycle_runner_callable\n            .last_receipt\n        )\n\n    assert (\n        receipts[0]\n        .lineage_completion_receipt\n        .lineage_wiring_receipt\n        .lineage_record_count_after\n        == 5\n    )\n    assert (\n        receipts[1]\n        .lineage_completion_receipt\n        .lineage_wiring_receipt\n        .lineage_record_count_after\n        == 10\n    )\n    assert (\n        receipts[2]\n        .lineage_completion_receipt\n        .lineage_wiring_receipt\n        .lineage_record_count_after\n        == 15\n    )\n    assert (\n        receipts[2]\n        .lineage_completion_receipt\n        .lineage_wiring_receipt\n        .transition_count\n        == 1\n    )\n\n    ledger = (\n        binding\n        .composition\n        .production_wiring\n        .lineage_bridge\n        .coordinator\n        .lineage_cycle_bridge\n        .batch_router\n        .bridge\n        .ledger\n    )\n\n    assert ledger.market_count == 5\n    assert ledger.record_count == 15\n\n    return binding, receipts\n\n\ndef run_deterministic_binding_replay_test():\n    def execute():\n        binding, _, _ = build_binding()\n        receipts = []\n\n        for cycle_number, observed_at, changed_market in (\n            (1, T1, None),\n            (2, T2, None),\n            (\n                3,\n                T3,\n                "KXTEST-GRAPH-5",\n            ),\n        ):\n            binding.ola017_persistence_router.route_batch(\n                build_cohort(\n                    cycle_number=cycle_number,\n                    changed_market=changed_market,\n                ),\n                observed_at,\n            )\n\n            binding.shadow_cycle_runner_callable(\n                cycle_completed_at=observed_at,\n                cycle_kwargs={\n                    "cycle": cycle_number,\n                },\n            )\n\n            receipts.append(\n                binding\n                .shadow_cycle_runner_callable\n                .last_receipt\n            )\n\n        records = (\n            binding\n            .composition\n            .production_wiring\n            .lineage_bridge\n            .coordinator\n            .lineage_cycle_bridge\n            .batch_router\n            .bridge\n            .ledger\n            .records()\n        )\n\n        return tuple(receipts), records\n\n    first_receipts, first_records = execute()\n    second_receipts, second_records = execute()\n\n    assert first_receipts == second_receipts\n    assert first_records == second_records\n\n    return first_receipts, first_records\n\n\ndef main():\n    binding, receipts = run_three_cycle_binding_test()\n\n    replay_receipts, replay_records = (\n        run_deterministic_binding_replay_test()\n    )\n\n    record = binding.record\n\n    result = {\n        "schema_version": record.schema_version,\n        "engine_id": record.engine_id,\n        "status": "passed",\n        "production_persistence_router_preserved": True,\n        "production_scheduler_callable_preserved": True,\n        "runtime_and_ola017_same_staged_router": True,\n        "shadow_cycle_runner_uses_ola_046_adapter": True,\n        "ola_047_shared_composition_consumed": True,\n        "ola_044_shared_production_wiring_identity": True,\n        "shared_lineage_state_identity": True,\n        "first_cycle_lineage_record_count": (\n            receipts[0]\n            .lineage_completion_receipt\n            .lineage_wiring_receipt\n            .lineage_record_count_after\n        ),\n        "second_cycle_lineage_record_count": (\n            receipts[1]\n            .lineage_completion_receipt\n            .lineage_wiring_receipt\n            .lineage_record_count_after\n        ),\n        "third_cycle_lineage_record_count": (\n            receipts[2]\n            .lineage_completion_receipt\n            .lineage_wiring_receipt\n            .lineage_record_count_after\n        ),\n        "third_cycle_transition_count": (\n            receipts[2]\n            .lineage_completion_receipt\n            .lineage_wiring_receipt\n            .transition_count\n        ),\n        "scheduler_kwargs_unchanged": True,\n        "scheduler_results_unchanged": True,\n        "deterministic_graph_binding_replay_valid": (\n            len(replay_receipts) == 3\n            and len(replay_records) == 15\n        ),\n        "ready_for_ola_030_graph_integration": True,\n        "no_acquisition_owned": True,\n        "no_persistence_owned": True,\n        "no_intelligence_interpretation": True,\n        "no_signal_scoring": True,\n        "alerts_allowed": False,\n        "qseries_handoff_allowed": False,\n        "read_only": record.read_only,\n        "execution_allowed": record.execution_allowed,\n        "execution_adapter_resolved": (\n            record.execution_adapter_resolved\n        ),\n        "execution_adapter_invoked": (\n            record.execution_adapter_invoked\n        ),\n        "trade_authorization_allowed": (\n            record.trade_authorization_allowed\n        ),\n        "order_placement_allowed": (\n            record.order_placement_allowed\n        ),\n        "funds_moved": record.funds_moved,\n        "portfolio_mutated": record.portfolio_mutated,\n    }\n\n    print(\n        "[PASS] OLA-048 Oracle Live Shadow Lineage "\n        "Graph Binding Contract"\n    )\n    print(result)\n\n\nif __name__ == "__main__":\n    main()\n'


def write_full_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        source,
        encoding="utf-8",
        newline="\n",
    )
    print(f"[OK] FULL REPLACEMENT: {path}")


def main() -> None:
    print("========================================")
    print(" OLA-048 INSTALLER")
    print(" LIVE SHADOW LINEAGE GRAPH BINDING")
    print("========================================")

    write_full_replacement(
        PRODUCTION_PATH,
        PRODUCTION_SOURCE,
    )
    write_full_replacement(
        TEST_PATH,
        TEST_SOURCE,
    )

    print()
    print(
        "[DONE] OLA-048 Oracle Live Shadow Lineage "
        "Graph Binding Contract installed"
    )
    print()
    print("Run:")
    print(
        "py test_ola_048_oracle_live_shadow_"
        "lineage_graph_binding_contract.py"
    )


if __name__ == "__main__":
    main()
